use crate::pet::Pet;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

pub fn generate_post_commit_hook_script(binary_path: Option<&str>) -> String {
    let bin = binary_path
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .unwrap_or("rustagotchi");

    format!(
        "#!/usr/bin/env sh\n\
         # Auto-generated by rustagotchi\n\
         COMMIT_HASH=$(git rev-parse --short HEAD 2>/dev/null)\n\
         COMMIT_MSG=$(git log -1 --pretty=%B 2>/dev/null | head -n 1)\n\
         {bin} --git-commit \"$COMMIT_HASH: $COMMIT_MSG\" >/dev/null 2>&1 || true\n"
    )
}

pub fn install_post_commit_hook(
    repo_root: impl AsRef<Path>,
    binary_path: Option<&str>,
) -> Result<PathBuf, String> {
    let root = repo_root.as_ref();
    let git_dir = root.join(".git");
    if !git_dir.exists() {
        return Err(format!(
            "No .git directory found at '{}'",
            git_dir.display()
        ));
    }

    let hooks_dir = git_dir.join("hooks");
    fs::create_dir_all(&hooks_dir)
        .map_err(|e| format!("Failed to create hooks directory '{}': {e}", hooks_dir.display()))?;

    let hook_path = hooks_dir.join("post-commit");
    let script = generate_post_commit_hook_script(binary_path);
    fs::write(&hook_path, script)
        .map_err(|e| format!("Failed to write post-commit hook '{}': {e}", hook_path.display()))?;

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let perms = fs::Permissions::from_mode(0o755);
        fs::set_permissions(&hook_path, perms)
            .map_err(|e| format!("Failed to set executable permissions on hook: {e}"))?;
    }

    Ok(hook_path)
}

pub fn sync_latest_commits(
    pet: &mut Pet,
    repo_root: impl AsRef<Path>,
    max_count: usize,
) -> Result<usize, String> {
    if max_count == 0 {
        return Ok(0);
    }

    let root = repo_root.as_ref();
    let output = Command::new("git")
        .arg("-C")
        .arg(root)
        .arg("log")
        .arg("-n")
        .arg(max_count.to_string())
        .arg("--pretty=format:%h:%s")
        .output()
        .map_err(|e| format!("Failed to execute git log: {e}"))?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("git log failed: {}", stderr.trim()));
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut rewarded = 0;
    for line in stdout.lines().rev() {
        let trimmed = line.trim();
        if !trimmed.is_empty() && pet.reward_git_commit(trimmed) {
            rewarded += 1;
        }
    }

    Ok(rewarded)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn unique_temp_dir(prefix: &str) -> PathBuf {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        std::env::temp_dir().join(format!("rustagotchi_{prefix}_{nanos}_{}", std::process::id()))
    }

    #[test]
    fn test_generate_post_commit_hook_script() {
        let default_script = generate_post_commit_hook_script(None);
        assert!(default_script.starts_with("#!/usr/bin/env sh\n"));
        assert!(default_script.contains("COMMIT_HASH=$(git rev-parse --short HEAD 2>/dev/null)"));
        assert!(default_script.contains("COMMIT_MSG=$(git log -1 --pretty=%B 2>/dev/null | head -n 1)"));
        assert!(default_script.contains("rustagotchi --git-commit \"$COMMIT_HASH: $COMMIT_MSG\""));

        let custom_script = generate_post_commit_hook_script(Some("/usr/local/bin/rustagotchi"));
        assert!(custom_script.contains("/usr/local/bin/rustagotchi --git-commit"));
    }

    #[test]
    fn test_install_post_commit_hook() {
        let tmp = unique_temp_dir("hook");
        fs::create_dir_all(&tmp).unwrap();

        let err = install_post_commit_hook(&tmp, None);
        assert!(err.is_err());

        fs::create_dir_all(tmp.join(".git")).unwrap();
        let hook_path = install_post_commit_hook(&tmp, Some("my-rustagotchi")).unwrap();
        assert!(hook_path.exists());

        let contents = fs::read_to_string(&hook_path).unwrap();
        assert!(contents.contains("my-rustagotchi --git-commit"));

        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = fs::metadata(&hook_path).unwrap().permissions().mode();
            assert_eq!(mode & 0o111, 0o111);
        }

        let _ = fs::remove_dir_all(&tmp);
    }

    #[test]
    fn test_sync_latest_commits_in_temp_repo() {
        let tmp = unique_temp_dir("git_sync");
        fs::create_dir_all(&tmp).unwrap();

        Command::new("git")
            .arg("-C")
            .arg(&tmp)
            .arg("init")
            .output()
            .unwrap();
        Command::new("git")
            .args(["-C", tmp.to_str().unwrap(), "config", "user.email", "test@example.com"])
            .output()
            .unwrap();
        Command::new("git")
            .args(["-C", tmp.to_str().unwrap(), "config", "user.name", "Tester"])
            .output()
            .unwrap();

        fs::write(tmp.join("file.txt"), "hello").unwrap();
        Command::new("git")
            .args(["-C", tmp.to_str().unwrap(), "add", "."])
            .output()
            .unwrap();
        Command::new("git")
            .args(["-C", tmp.to_str().unwrap(), "commit", "-m", "Initial commit"])
            .output()
            .unwrap();

        let mut pet = Pet::new("Ferris");
        let count1 = sync_latest_commits(&mut pet, &tmp, 5).unwrap();
        assert_eq!(count1, 1);
        assert_eq!(pet.commits_fed, 1);

        let count2 = sync_latest_commits(&mut pet, &tmp, 5).unwrap();
        assert_eq!(count2, 0);
        assert_eq!(pet.commits_fed, 1);

        let _ = fs::remove_dir_all(&tmp);
    }
}
